public static boolean isDigits(String str){
    if (str == null || str.isEmpty()) {
        return false;
    }
    for (int i = 0; i < str.length(); ) {
        int cp = str.codePointAt(i);
        if (!Character.isDigit(cp)) {
            return false;
        }
        i += Character.charCount(cp);
    }
    return true;
}

